# =============================================================================
# evaluate_false_positives.py
# AI Fraud Detection System — False Positive Reduction Evaluation
#
# IMPORTANT NOTE: This is a SIMULATED context layer on SYNTHETIC data.
# PaySim is a synthetic dataset generated by a simulation tool, so "customer
# averages" derived here are themselves synthetic. In production, these would
# come from a real customer profile database or feature store.
#
# This script compares:
#   BASELINE : Random Forest alone (threshold-based flagging)
#   ENHANCED : RF + customer-context layer (as in fraud_engine.py)
#
# It prints a before/after table showing:
#   - Genuine customers falsely flagged (false positives)
#   - Fraud caught (true positive recall)
#   - % reduction in false alerts
# =============================================================================

import os
import sys
import warnings

if sys.platform == "win32":
    try:
        sys.stdout.reconfigure(encoding="utf-8")
        sys.stderr.reconfigure(encoding="utf-8")
    except Exception:
        pass

import numpy as np
import pandas as pd
import joblib
from sklearn.ensemble import IsolationForest

warnings.filterwarnings("ignore")

# ---------------------------------------------------------------------------
# PATHS
# ---------------------------------------------------------------------------
DATASET_PATH = os.path.join("dataset", "paysim.csv")
MODELS_DIR   = "models"

# ---------------------------------------------------------------------------
# LOAD MODELS AND CONFIG
# ---------------------------------------------------------------------------
print("\n" + "="*65)
print("  FALSE POSITIVE REDUCTION EVALUATION")
print("="*65)
print("\n[1/5] Loading models ...")

try:
    rf_model      = joblib.load(os.path.join(MODELS_DIR, "fraud_model.pkl"))
    anomaly_model = joblib.load(os.path.join(MODELS_DIR, "anomaly_model.pkl"))
    config        = joblib.load(os.path.join(MODELS_DIR, "config.pkl"))
except FileNotFoundError:
    print("\n❌  Model files not found. Run `python train_model.py` first.")
    sys.exit(1)

FEATURE_COLUMNS   = config["feature_columns"]
ANOMALY_THRESHOLD = config["anomaly_threshold"]
RF_THRESHOLD      = config["rf_threshold"]

# ---------------------------------------------------------------------------
# LOAD DATASET — MUST MATCH TRAINING PREP
# ---------------------------------------------------------------------------
print(f"[2/5] Loading dataset from '{DATASET_PATH}' ...")

try:
    df = pd.read_csv(DATASET_PATH)
except FileNotFoundError:
    print(f"\n❌  Dataset not found at '{DATASET_PATH}'.")
    sys.exit(1)

RANDOM_STATE = 42
SAMPLE_SIZE  = 300_000

fraud_df = df[df["isFraud"] == 1].copy()
legit_df = df[df["isFraud"] == 0].copy()
legit_sample_size = max(0, SAMPLE_SIZE - len(fraud_df))

if len(df) > SAMPLE_SIZE:
    legit_sampled = legit_df.sample(
        n=min(legit_sample_size, len(legit_df)), random_state=RANDOM_STATE
    )
    df_sample = pd.concat([fraud_df, legit_sampled]).reset_index(drop=True)
else:
    df_sample = df.copy()

# Chronological split (same as train_model.py)
FEATURE_COLS_BASE = ["step", "amount", "oldbalanceOrg", "oldbalanceDest"]
type_dummies  = pd.get_dummies(df_sample["type"], prefix="type", dtype=int)
df_features   = pd.concat([df_sample[FEATURE_COLS_BASE], type_dummies], axis=1)
df_features   = df_features.reindex(columns=FEATURE_COLUMNS, fill_value=0)

X = df_features.values
y = df_sample["isFraud"].values

sort_idx    = df_sample["step"].argsort().values
X_sorted    = X[sort_idx]
y_sorted    = y[sort_idx]
df_sorted   = df_sample.iloc[sort_idx].reset_index(drop=True)

split_point     = int(len(X_sorted) * 0.80)
X_train, X_test = X_sorted[:split_point], X_sorted[split_point:]
y_train, y_test = y_sorted[:split_point], y_sorted[split_point:]
df_train        = df_sorted.iloc[:split_point].reset_index(drop=True)
df_test         = df_sorted.iloc[split_point:].reset_index(drop=True)

print(f"    Train rows: {len(X_train):,} | Test rows: {len(X_test):,}")

# ---------------------------------------------------------------------------
# STEP 3 — Derive PSEUDO customer_avg_amount from TRAINING data only
#
# NOTE: This is a simulation. In a real system this would come from a live
# customer profile store (e.g., Redis or a feature platform).
# We use training data only to avoid leaking test information.
# ---------------------------------------------------------------------------
print("[3/5] Deriving pseudo customer averages from training data only ...")

# Per-customer median transaction amount (from training set)
cust_avg_map    = df_train.groupby("nameOrig")["amount"].median().to_dict()
global_median   = df_train["amount"].median()

def get_cust_avg(name):
    """Return customer average, falling back to global median if unknown."""
    return cust_avg_map.get(name, global_median)

# Apply to test set
test_names     = df_test["nameOrig"].values
cust_avgs_test = np.array([get_cust_avg(n) for n in test_names])

# ---------------------------------------------------------------------------
# STEP 4 — Score test set under both strategies
# ---------------------------------------------------------------------------
print("[4/5] Scoring test set (baseline vs enhanced) ...")

# RF probabilities on test set
y_proba_test = rf_model.predict_proba(X_test)[:, 1]

# IsolationForest scores on test set
iso_scores_test = anomaly_model.decision_function(X_test)
is_anomaly_test = iso_scores_test < ANOMALY_THRESHOLD

# --- BASELINE: flag if RF probability >= RF_THRESHOLD ---
baseline_flags = (y_proba_test >= RF_THRESHOLD).astype(int)

# --- ENHANCED: apply the same 4-tier customer context logic ---
# A transaction is "familiar" if the amount is at most 1.5× the customer's
# typical amount. (In production this would also include behaviour signals.)
familiar_test = (df_test["amount"].values <= 1.5 * cust_avgs_test)

enhanced_flags = np.zeros(len(y_test), dtype=int)

for i in range(len(y_test)):
    prob       = y_proba_test[i]
    is_anom    = bool(is_anomaly_test[i])
    cust_avg   = float(cust_avgs_test[i])
    amount     = float(df_test.iloc[i]["amount"])
    familiar   = bool(familiar_test[i])

    # Normal customer pattern definition (matches fraud_engine.py)
    normal_cust = (cust_avg > 0 and amount <= 1.5 * cust_avg and familiar)

    # Tier 1: HIGH RISK — always flag
    if prob >= 0.80:
        enhanced_flags[i] = 1

    # Tier 2: MEDIUM RISK — elevated probability or anomaly, context can't clear
    elif (prob >= 0.30 or is_anom) and not (normal_cust and prob < 0.50):
        enhanced_flags[i] = 1

    # Tier 3: Context clears the flag — do NOT flag
    # Tier 4: Low risk — do NOT flag
    else:
        enhanced_flags[i] = 0

# ---------------------------------------------------------------------------
# STEP 5 — Compute and print before/after table
# ---------------------------------------------------------------------------
print("[5/5] Computing results ...\n")

# True positive = fraud correctly flagged
# False positive = genuine customer incorrectly flagged

y_test_arr = np.array(y_test)

def metrics(flags, truth):
    tp = int(((flags == 1) & (truth == 1)).sum())
    fp = int(((flags == 1) & (truth == 0)).sum())
    tn = int(((flags == 0) & (truth == 0)).sum())
    fn = int(((flags == 0) & (truth == 1)).sum())
    recall    = tp / (tp + fn) if (tp + fn) > 0 else 0.0
    precision = tp / (tp + fp) if (tp + fp) > 0 else 0.0
    fpr       = fp / (fp + tn) if (fp + tn) > 0 else 0.0
    return tp, fp, tn, fn, recall, precision, fpr

b_tp, b_fp, b_tn, b_fn, b_rec, b_prec, b_fpr = metrics(baseline_flags, y_test_arr)
e_tp, e_fp, e_tn, e_fn, e_rec, e_prec, e_fpr = metrics(enhanced_flags, y_test_arr)

fp_reduction  = (b_fp - e_fp) / b_fp * 100 if b_fp > 0 else 0.0
rec_change    = (e_rec - b_rec) * 100

print("="*65)
print(f"{'Metric':<40} {'Baseline':>10} {'Enhanced':>10}")
print("="*65)
print(f"{'Genuine customers falsely flagged (FP)':<40} {b_fp:>10,} {e_fp:>10,}")
print(f"{'Fraud caught — True Positives (TP)':<40} {b_tp:>10,} {e_tp:>10,}")
print(f"{'Fraud missed — False Negatives (FN)':<40} {b_fn:>10,} {e_fn:>10,}")
print(f"{'Fraud Recall (%)':<40} {b_rec*100:>9.2f}% {e_rec*100:>9.2f}%")
print(f"{'Precision (%)':<40} {b_prec*100:>9.2f}% {e_prec*100:>9.2f}%")
print(f"{'False Positive Rate (%)':<40} {b_fpr*100:>9.2f}% {e_fpr*100:>9.2f}%")
print("="*65)
print(f"\n  🎯  False Alert Reduction : {fp_reduction:+.1f}%")
print(f"  📉  Recall Change         : {rec_change:+.2f} percentage points")
print()
print(
    "NOTE: 'Familiar pattern' is simulated from per-customer medians in\n"
    "training data only. In production, this would come from a real-time\n"
    "customer profile / feature store. PaySim is fully synthetic data.\n"
)
print("="*65 + "\n")
